theory.code:
"  Jan.Kowalski@Example.COM  "
  .trim()          -> "Jan.Kowalski@Example.COM"
  .toLowerCase()   -> "jan.kowalski@example.com"

// jedna linia, ale DWA niezalezne kroki wykonane po kolei:
const email = "  Jan.Kowalski@Example.COM  ";
console.log(email.trim().toLowerCase()); // "jan.kowalski@example.com"

const path = "/api/users/42";
console.log(path.startsWith("/api"));  // true
console.log(path.endsWith("/42"));     // true
console.log(path.replace("/api", "")); // "/users/42"
console.log(path.slice(5));            // "users/42"
console.log(path.indexOf("users"));    // 5

const csv = "Jan,Kowalski,jan@example.com,admin";
const [firstName, lastName, userEmail, role] = csv.split(",");
console.log(firstName, role); // "Jan" "admin"

let nazwa = "  Jan  ";
nazwa.trim(); // wynik OBLICZONY, ale NIGDZIE nie zapisany
console.log(nazwa); // "  Jan  " - BEZ ZMIAN! trim() nie zmienil oryginalu

let nazwa = "  Jan  ";
nazwa = nazwa.trim(); // wynik JAWNIE przypisany z powrotem
console.log(nazwa); // "Jan" - POPRAWNIE, bez spacji

exercises.solution:
const plik = "raport-2024.pdf";
console.log(plik.startsWith("raport")); // true
console.log(plik.endsWith(".pdf"));     // true

const kod = "kod:1234";
const indeksDwukropka = kod.indexOf(":");
console.log(kod.slice(indeksDwukropka + 1)); // "1234"

const zdanie = "Kot siedzi na macie";
console.log(zdanie.startsWith("Kot"));   // true
console.log(zdanie.endsWith("macie"));   // true

function znormalizujEmail(email) {
  return email.trim().toLowerCase();
}

console.log(znormalizujEmail("  Ola.NOWAK@Firma.COM  "));
// "ola.nowak@firma.com"

function wyodrebnijDomeny(email) {
  const indeksMalpy = email.indexOf("@");
  return email.slice(indeksMalpy + 1);
}

console.log(wyodrebnijDomeny("user@example.com")); // "example.com"
